begin;
update public.explorer_windows as map_window set median_slope_deg = score.median_slope_deg, terrain_roughness_m = score.terrain_roughness_m, relative_relief_m = score.relative_relief_m from public.candidate_scores as score where map_window.scenario_id = score.scenario_id and map_window.model_run_id = score.model_run_id and map_window.candidate_id = score.candidate_id and map_window.candidate_id is not null;
update public.explorer_windows as map_window set median_slope_deg = reference.slope, terrain_roughness_m = reference.roughness, relative_relief_m = reference.relief from (select max(reference_raw_value) filter (where feature_key = 'median_slope_deg') as slope, max(reference_raw_value) filter (where feature_key = 'terrain_roughness_m') as roughness, max(reference_raw_value) filter (where feature_key = 'relative_relief_m') as relief from public.ranking_contributions where scenario_id = 'mars-gale-aeolis-palus-v1' and model_run_id = '2026-11-14-mvp-v1') as reference where map_window.scenario_id = 'mars-gale-aeolis-palus-v1' and map_window.model_run_id = '2026-11-14-mvp-v1' and map_window.candidate_id is null;
update public.model_runs set status = 'ready' where id = '2026-11-14-mvp-v1';
commit;
